"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["22662"],{17803(e){e.exports=JSON.parse('{"id":"FIN-551","slug":"tax-evasion","term":"Tax Evasion","also_known_as":[],"difficulty":"Beginner","definition":"Tax evasion is the illegal practice of not paying tax that is owed, for example by hiding income, inflating deductions or providing false information to tax authorities.","explanation":["Tax evasion breaks the law. Common examples include not declaring cash income, keeping money in undisclosed offshore accounts, claiming expenses that were never incurred, underreporting sales and falsifying records.","For example, a business owner who takes 50,000 of cash payments a year and leaves them out of the accounts to reduce taxable profit is committing tax evasion.","Penalties can be severe. They may include repayment of the tax owed, interest, large fines and, in serious cases, criminal prosecution and imprisonment. Tax authorities increasingly use data sharing between countries, bank reporting and analytics to detect evasion.","Tax evasion differs from tax avoidance. Avoidance means using the rules legally to reduce tax, even if some arrangements are aggressive. Evasion means deliberately breaking the rules.","Evasion has wider effects too. It reduces the money available for public services, shifts more of the tax burden onto honest taxpayers and gives evaders an unfair advantage over businesses that pay what they owe. Governments therefore treat it as a serious offence."],"note":"","total":1500,"prev":{"slug":"tax-efficient-investing","term":"Tax-Efficient Investing"},"next":{"slug":"tax-exemption","term":"Tax Exemption"}}')}}]);